window.ASTRYL_SHEET={"sun":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/sun.webp\" alt=\"Sun\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Sun</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Our star, the centre of the Solar System</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,392,700 km</span><span class=\"t\" lang=\"hi\">13,92,700 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">274 m/s² (27.96 g)</span><span class=\"t\" lang=\"hi\">274 m/s² (27.96 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,500 °C</span><span class=\"t\" lang=\"hi\">5,500 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">25.4 days</span><span class=\"t\" lang=\"hi\">25.4 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">–</span><span class=\"t\" lang=\"hi\">–</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0</span><span class=\"t\" lang=\"hi\">0</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">–</span><span class=\"t\" lang=\"hi\">–</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 50 million years to start shining steadily</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">A small part of a huge cloud of gas and dust collapsed under its own gravity, perhaps pushed by the blast of a nearby exploding star. The centre grew hot and dense until hydrogen began to fuse into helium. Everything else in the solar system formed from the flat, spinning disk left around it.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span></div><p><span class=\"t\" lang=\"en\">The cloud collapses; the oldest solid grains in meteorites date from this moment (4.567 billion years).</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First 100,000 years</span></div><p><span class=\"t\" lang=\"en\">A glowing young star (a protostar) forms in the centre, wrapped in a disk of gas and dust.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 50 million years later</span></div><p><span class=\"t\" lang=\"en\">Hydrogen fusion starts in the core and the Sun becomes a steady, grown-up star.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span></div><p><span class=\"t\" lang=\"en\">About halfway through its life; it is about 30% brighter than when it was young.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">In about 5 billion years</span></div><p><span class=\"t\" lang=\"en\">It swells into a red giant, then shrinks into a white dwarf.</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">The Sun holds 99.8% of all the mass in the solar system.</span></li><li><span class=\"t\" lang=\"en\">Sunlight takes about 8 minutes and 20 seconds to reach Earth.</span></li></ul><p><a class=\"btn primary\" href=\"body/sun.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"mercury":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/mercury.webp\" alt=\"Mercury\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Mercury</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 1 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,879 km</span><span class=\"t\" lang=\"hi\">4,879 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.7 m/s² (0.38 g)</span><span class=\"t\" lang=\"hi\">3.7 m/s² (0.38 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">167 °C</span><span class=\"t\" lang=\"hi\">167 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">175.9 days</span><span class=\"t\" lang=\"hi\">175.9 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">88 days</span><span class=\"t\" lang=\"hi\">88 दिन</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0</span><span class=\"t\" lang=\"hi\">0</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">57.9 million km</span><span class=\"t\" lang=\"hi\">57.9 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Probably a few tens of millions of years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Rocky grains near the hot young Sun stuck together into bigger and bigger bodies that crashed and merged. Mercury ended up with a giant iron core that fills most of the planet.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Dust and rock near the Sun clump into small planet seeds.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First tens of millions of years</span></div><p><span class=\"t\" lang=\"en\">The seeds collide and merge into Mercury; heavy iron sinks to the centre.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.1 to 3.8 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Big impacts and lava floods shape the surface; huge basins like Caloris form.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Since then</span></div><p><span class=\"t\" lang=\"en\">The planet slowly cools and shrinks, wrinkling its crust into long cliffs.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Why is the iron core so big? A giant impact may have knocked away much of the rocky outer layer, but MESSENGER found easily-lost elements like sulfur and potassium on the surface, which a very violent past would have boiled away.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">One day on Mercury, from sunrise to the next sunrise, lasts about 176 Earth days. That is twice as long as its year.</span></li><li><span class=\"t\" lang=\"en\">Mercury has almost no air, so its sky is black even by day, and its nights are freezing cold.</span></li></ul><p><a class=\"btn primary\" href=\"body/mercury.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"venus":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/venus.webp\" alt=\"Venus\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Venus</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 2 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">12,104 km</span><span class=\"t\" lang=\"hi\">12,104 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">8.9 m/s² (0.91 g)</span><span class=\"t\" lang=\"hi\">8.9 m/s² (0.91 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">464 °C</span><span class=\"t\" lang=\"hi\">464 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">116.8 days</span><span class=\"t\" lang=\"hi\">116.8 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">224.7 days</span><span class=\"t\" lang=\"hi\">224.7 दिन</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0</span><span class=\"t\" lang=\"hi\">0</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">108.2 million km</span><span class=\"t\" lang=\"hi\">108.2 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">92 bar</span><span class=\"t\" lang=\"hi\">92 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About as long as Earth, tens of millions of years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Venus grew the same way as Earth and to almost the same size. Its story split from Earth&#x27;s later: its air filled with carbon dioxide and trapped so much heat that any water boiled away.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Rocky planet seeds merge into Venus, close to Earth&#x27;s size.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on (unsure)</span></div><p><span class=\"t\" lang=\"en\">It may have had shallow oceans while the young Sun was dimmer.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Later</span></div><p><span class=\"t\" lang=\"en\">A runaway greenhouse effect heats the planet; water escapes to space.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 300 to 700 million years ago</span></div><p><span class=\"t\" lang=\"en\">Lava covers most of the surface, so the ground we see is fairly young.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Did Venus ever have oceans, and for how long? Missions planned for the 2030s (VERITAS, DAVINCI, EnVision) are meant to find out.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Venus spins backwards, so on Venus the Sun rises in the west.</span></li><li><span class=\"t\" lang=\"en\">Venus is hotter than Mercury, even though it is farther from the Sun, because its thick air traps the heat.</span></li></ul><p><a class=\"btn primary\" href=\"body/venus.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"earth":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/earth.webp\" alt=\"Earth\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Earth</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 3 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">12,756 km</span><span class=\"t\" lang=\"hi\">12,756 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">9.8 m/s² (1 g)</span><span class=\"t\" lang=\"hi\">9.8 m/s² (1 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">15 °C</span><span class=\"t\" lang=\"hi\">15 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">24 h</span><span class=\"t\" lang=\"hi\">24 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">365.2 days</span><span class=\"t\" lang=\"hi\">365.2 दिन</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1</span><span class=\"t\" lang=\"hi\">1</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">149.6 million km</span><span class=\"t\" lang=\"hi\">149.6 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1 bar</span><span class=\"t\" lang=\"hi\">1 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.54 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 30 to 100 million years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Earth grew from rocky planet seeds that collided and merged. Heavy iron sank to form the core. A Mars-sized body called Theia then hit the young Earth, and the debris formed the Moon.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.54 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Planet seeds merge; Earth grows and heats up.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">In the first ~30 million years</span></div><p><span class=\"t\" lang=\"en\">Iron sinks to the centre and forms the core.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.5 billion years ago</span></div><p><span class=\"t\" lang=\"en\">The giant impact with Theia; the Moon forms from the debris.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.4 billion years ago</span></div><p><span class=\"t\" lang=\"en\">The oldest known crystals (zircons) show that liquid water already existed.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">At least 3.5 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Life appears; about 2.4 billion years ago microbes fill the air with oxygen.</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Earth is the only place we know with life, and about 71% of its surface is covered by water.</span></li><li><span class=\"t\" lang=\"en\">Earth is not a perfect ball. It bulges a little at the equator because it spins.</span></li></ul><h3><span class=\"t\" lang=\"en\">Major moons</span></h3><div class=\"sheetmoons\"><a href=\"body/moon.html\"><img class=\"pimg\" src=\"img/planets/moon-s.webp\" alt=\"Moon\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Moon</span></span></a></div><p><a class=\"btn primary\" href=\"body/earth.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"mars":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/mars.webp\" alt=\"Mars\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Mars</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 4 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">6,792 km</span><span class=\"t\" lang=\"hi\">6,792 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.7 m/s² (0.38 g)</span><span class=\"t\" lang=\"hi\">3.7 m/s² (0.38 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-65 °C</span><span class=\"t\" lang=\"hi\">-65 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">24.7 h</span><span class=\"t\" lang=\"hi\">24.7 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">687 days</span><span class=\"t\" lang=\"hi\">687 दिन</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2</span><span class=\"t\" lang=\"hi\">2</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">228 million km</span><span class=\"t\" lang=\"hi\">228 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.006 bar</span><span class=\"t\" lang=\"hi\">0.006 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Fast: about 2 to 4 million years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Mars formed quickly and then stopped growing, which is why it stayed small. Meteorites from Mars show its core formed only a few million years after the solar system began. It once had rivers and lakes, then lost its magnetic field and most of its air.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Mars grows to nearly full size within a few million years.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.1 to 3.7 billion years ago</span></div><p><span class=\"t\" lang=\"en\">A warmer, wetter time: rivers carve valleys and lakes fill craters like Jezero.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Its global magnetic field fades; the solar wind strips away much of the air.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Until recently</span></div><p><span class=\"t\" lang=\"en\">Giant volcanoes like Olympus Mons erupt from time to time; today Mars is cold and dry.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Was early Mars warm for a long time or only in short bursts, and did life ever start there? Perseverance is collecting rock samples to help answer this.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Olympus Mons on Mars is the tallest volcano in the solar system, about two and a half times as tall as Mount Everest.</span></li><li><span class=\"t\" lang=\"en\">Sunsets on Mars look blue.</span></li></ul><p><a class=\"btn primary\" href=\"body/mars.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"jupiter":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/jupiter.webp\" alt=\"Jupiter\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Jupiter</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 5 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">142,984 km</span><span class=\"t\" lang=\"hi\">1,42,984 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">23.1 m/s² (2.36 g)</span><span class=\"t\" lang=\"hi\">23.1 m/s² (2.36 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-110 °C</span><span class=\"t\" lang=\"hi\">-110 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">9.9 h</span><span class=\"t\" lang=\"hi\">9.9 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">11.9 years</span><span class=\"t\" lang=\"hi\">11.9 वर्ष</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">115</span><span class=\"t\" lang=\"hi\">115</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, the first planet</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Its core in about 1 million years; the gas within a few million</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Beyond the &quot;snow line&quot;, where water froze into ice, a solid core grew quickly to many times Earth&#x27;s mass. Its gravity then pulled in huge amounts of hydrogen and helium gas. Jupiter was the first planet, and its gravity shaped where the others could form.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First ~1 million years</span></div><p><span class=\"t\" lang=\"en\">A core of rock and ice grows to about 20 times Earth&#x27;s mass.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Up to ~3 to 4 million years</span></div><p><span class=\"t\" lang=\"en\">It pulls in gas fast; meteorites show it split the young disk into an inner and an outer part.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Within ~10 million years</span></div><p><span class=\"t\" lang=\"en\">The gas disk is gone; Jupiter has its full size, and its big moons form around it.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span></div><p><span class=\"t\" lang=\"en\">Juno found its core is not a small solid ball but &quot;fuzzy&quot;, spread out and mixed with gas.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Did Jupiter move inward toward the Sun and back out again early on (the &quot;Grand Tack&quot; idea)? It could explain why Mars is small, but it is not proven.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Jupiter has more than twice the mass of all the other planets put together.</span></li><li><span class=\"t\" lang=\"en\">The Great Red Spot is a storm bigger than Earth, and people have watched it for more than 150 years.</span></li></ul><h3><span class=\"t\" lang=\"en\">Major moons</span></h3><div class=\"sheetmoons\"><a href=\"body/io.html\"><img class=\"pimg\" src=\"img/planets/io-s.webp\" alt=\"Io\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Io</span></span></a><a href=\"body/europa.html\"><img class=\"pimg\" src=\"img/planets/europa-s.webp\" alt=\"Europa\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Europa</span></span></a><a href=\"body/ganymede.html\"><img class=\"pimg\" src=\"img/planets/ganymede-s.webp\" alt=\"Ganymede\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Ganymede</span></span></a><a href=\"body/callisto.html\"><img class=\"pimg\" src=\"img/planets/callisto-s.webp\" alt=\"Callisto\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Callisto</span></span></a></div><p><a class=\"btn primary\" href=\"body/jupiter.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"saturn":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/saturn.webp\" alt=\"Saturn\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Saturn</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 6 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">120,536 km</span><span class=\"t\" lang=\"hi\">1,20,536 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">9 m/s² (0.92 g)</span><span class=\"t\" lang=\"hi\">9 m/s² (0.92 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-140 °C</span><span class=\"t\" lang=\"hi\">-140 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">10.7 h</span><span class=\"t\" lang=\"hi\">10.7 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">29.4 years</span><span class=\"t\" lang=\"hi\">29.4 वर्ष</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">293</span><span class=\"t\" lang=\"hi\">293</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,432 million km</span><span class=\"t\" lang=\"hi\">1,432 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">A few million years, soon after Jupiter</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Saturn formed like Jupiter: an icy core first, then a thick blanket of hydrogen and helium. It grew a little later and caught less gas before the disk faded. Its famous rings came much later.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span></div><p><span class=\"t\" lang=\"en\">An ice-and-rock core grows beyond Jupiter&#x27;s orbit.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Before ~10 million years</span></div><p><span class=\"t\" lang=\"en\">It pulls in gas until the disk around the Sun runs out.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Soon after</span></div><p><span class=\"t\" lang=\"en\">Titan and the other moons form in a disk around Saturn.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Perhaps a few hundred million years ago</span></div><p><span class=\"t\" lang=\"en\">Cassini&#x27;s measurements suggest the rings may be only a few hundred million years old or less, but scientists still debate it.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Are the rings young, from a moon or comet torn apart, or as old as Saturn itself and just kept clean? Both ideas still have supporters.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Saturn is so light for its size that it would float in water, if you could find a bathtub big enough.</span></li><li><span class=\"t\" lang=\"en\">Saturn&#x27;s rings are very wide but very thin: in places only about ten metres thick.</span></li></ul><h3><span class=\"t\" lang=\"en\">Major moons</span></h3><div class=\"sheetmoons\"><a href=\"body/titan.html\"><img class=\"pimg\" src=\"img/planets/titan-s.webp\" alt=\"Titan\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Titan</span></span></a><a href=\"body/enceladus.html\"><img class=\"pimg\" src=\"img/planets/enceladus-s.webp\" alt=\"Enceladus\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Enceladus</span></span></a></div><p><a class=\"btn primary\" href=\"body/saturn.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"uranus":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/uranus.webp\" alt=\"Uranus\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Uranus</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 7 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">51,118 km</span><span class=\"t\" lang=\"hi\">51,118 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">8.7 m/s² (0.89 g)</span><span class=\"t\" lang=\"hi\">8.7 m/s² (0.89 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-195 °C</span><span class=\"t\" lang=\"hi\">-195 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">17.2 h</span><span class=\"t\" lang=\"hi\">17.2 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">83.7 years</span><span class=\"t\" lang=\"hi\">83.7 वर्ष</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">29</span><span class=\"t\" lang=\"hi\">29</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2,867 million km</span><span class=\"t\" lang=\"hi\">2,867 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Longer than Jupiter and Saturn, perhaps several million years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Uranus grew a large core of ice and rock, but the gas disk was fading by then, so it caught only a thin layer of hydrogen and helium. That is why it is an &quot;ice giant&quot;. It probably formed closer to the Sun and moved outward later. Something big knocked it onto its side.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span></div><p><span class=\"t\" lang=\"en\">An ice-rich core grows, probably closer to the Sun than today.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">As the gas fades</span></div><p><span class=\"t\" lang=\"en\">It gathers only a thin hydrogen-helium envelope.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span></div><p><span class=\"t\" lang=\"en\">One or more giant impacts tilt it to about 98 degrees, rolling it around the Sun on its side.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few hundred million years</span></div><p><span class=\"t\" lang=\"en\">The giant planets shuffle their orbits and Uranus settles farther out.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Exactly what tipped Uranus over, and why it gives off so little inner heat, is still unknown. Only Voyager 2 has visited, in 1986.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Uranus rolls around the Sun on its side, tilted by about 98 degrees.</span></li><li><span class=\"t\" lang=\"en\">Uranus was the first planet found with a telescope. William Herschel spotted it in 1781.</span></li></ul><p><a class=\"btn primary\" href=\"body/uranus.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"neptune":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/neptune.webp\" alt=\"Neptune\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Neptune</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Planet 8 from the Sun</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">49,528 km</span><span class=\"t\" lang=\"hi\">49,528 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">11 m/s² (1.12 g)</span><span class=\"t\" lang=\"hi\">11 m/s² (1.12 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-200 °C</span><span class=\"t\" lang=\"hi\">-200 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16.1 h</span><span class=\"t\" lang=\"hi\">16.1 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">163.7 years</span><span class=\"t\" lang=\"hi\">163.7 वर्ष</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16</span><span class=\"t\" lang=\"hi\">16</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,515 million km</span><span class=\"t\" lang=\"hi\">4,515 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Several million years, like Uranus</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Neptune is Uranus&#x27;s twin: a big ice-and-rock core with a thinner gas layer. It most likely formed closer to the Sun and was pushed outward, scattering icy bodies and shaping the Kuiper Belt beyond it.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span></div><p><span class=\"t\" lang=\"en\">An icy core grows and collects a thin envelope of gas.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few hundred million years</span></div><p><span class=\"t\" lang=\"en\">It migrates outward, scattering icy bodies; some are flung toward the inner planets.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">During the move</span></div><p><span class=\"t\" lang=\"en\">It pushes Pluto and other bodies into step with its own orbit (2 Pluto years for every 3 Neptune years).</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Later</span></div><p><span class=\"t\" lang=\"en\">It captures Triton, a dwarf planet from the Kuiper Belt.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">The exact path of the giant planets&#x27; move (the &quot;Nice model&quot;) is still being worked out.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Neptune has the fastest winds of any planet, more than 2,000 km/h.</span></li><li><span class=\"t\" lang=\"en\">Neptune was found with maths before anyone saw it: in 1846 astronomers worked out where it had to be.</span></li></ul><h3><span class=\"t\" lang=\"en\">Major moons</span></h3><div class=\"sheetmoons\"><a href=\"body/triton.html\"><img class=\"pimg\" src=\"img/planets/triton-s.webp\" alt=\"Triton\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\">Triton</span></span></a></div><p><a class=\"btn primary\" href=\"body/neptune.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"pluto":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/pluto.webp\" alt=\"Pluto\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Pluto</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Dwarf planet</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2,376 km</span><span class=\"t\" lang=\"hi\">2,376 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.6 m/s² (0.06 g)</span><span class=\"t\" lang=\"hi\">0.6 m/s² (0.06 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-225 °C</span><span class=\"t\" lang=\"hi\">-225 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">6.4 days</span><span class=\"t\" lang=\"hi\">6.4 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">247.9 years</span><span class=\"t\" lang=\"hi\">247.9 वर्ष</span></b><span><span class=\"t\" lang=\"en\">Year</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5</span><span class=\"t\" lang=\"hi\">5</span></b><span><span class=\"t\" lang=\"en\">Known moons</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,906.4 million km</span><span class=\"t\" lang=\"hi\">5,906.4 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">&lt; 0.001 bar</span><span class=\"t\" lang=\"hi\">&lt; 0.001 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Unknown; it grew slowly from icy bodies far from the Sun</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Pluto formed in the cold outer disk from icy pebbles and small bodies, like many other Kuiper Belt objects. Its big moon Charon was probably made by a slow, glancing collision. Neptune&#x27;s outward move later locked Pluto into its present orbit.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Icy pebbles in the far disk gather into small worlds.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span></div><p><span class=\"t\" lang=\"en\">A collision with another body forms Charon and Pluto&#x27;s small moons.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few hundred million years</span></div><p><span class=\"t\" lang=\"en\">Neptune moves outward and pushes Pluto into its tilted, stretched orbit.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Recent</span></div><p><span class=\"t\" lang=\"en\">New Horizons (2015) found young ice plains with no craters, so Pluto is still active.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">What keeps Pluto active so far from the Sun? A hidden ocean under the ice is one possible answer.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">A year on Pluto lasts about 248 Earth years.</span></li><li><span class=\"t\" lang=\"en\">Pluto has a huge heart-shaped plain of frozen nitrogen.</span></li></ul><p><a class=\"btn primary\" href=\"body/pluto.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"moon":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/moon.webp\" alt=\"Moon\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Moon</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Earth</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3,475 km</span><span class=\"t\" lang=\"hi\">3,475 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.6 m/s² (0.17 g)</span><span class=\"t\" lang=\"hi\">1.6 m/s² (0.17 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-23 °C</span><span class=\"t\" lang=\"hi\">-23 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">29.5 days</span><span class=\"t\" lang=\"hi\">29.5 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">27.3 days</span><span class=\"t\" lang=\"hi\">27.3 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">149.6 million km</span><span class=\"t\" lang=\"hi\">149.6 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">384,400 km</span><span class=\"t\" lang=\"hi\">3,84,400 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Earth</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.5 billion years ago</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Very fast: perhaps hours to a few years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">A Mars-sized body called Theia hit the young Earth. Molten rock was thrown into orbit and gathered into the Moon. Apollo rocks have almost the same make-up as Earth&#x27;s rocks, which supports this idea.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.5 billion years ago</span></div><p><span class=\"t\" lang=\"en\">The giant impact; a ring of molten debris circles Earth and clumps into the Moon.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Next ~100 million years</span></div><p><span class=\"t\" lang=\"en\">A global ocean of magma cools; light rock floats up to form the bright highlands.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 3.9 to 3.1 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Lava fills huge impact basins, making the dark &quot;seas&quot; (maria) we see.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Since then</span></div><p><span class=\"t\" lang=\"en\">Mostly quiet; the Moon drifts away from Earth by about 3.8 cm a year.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">The details of the impact are still argued: how big Theia was, how fast it hit, and why the Moon&#x27;s rocks match Earth&#x27;s so closely.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">The Moon moves about 3.8 centimetres farther from Earth every year.</span></li><li><span class=\"t\" lang=\"en\">We always see the same side of the Moon, because it turns exactly once for each trip around Earth.</span></li></ul><p><a class=\"btn primary\" href=\"body/moon.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"io":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/io.webp\" alt=\"Io\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Io</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Jupiter</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3,643 km</span><span class=\"t\" lang=\"hi\">3,643 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.8 m/s² (0.18 g)</span><span class=\"t\" lang=\"hi\">1.8 m/s² (0.18 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-143 °C</span><span class=\"t\" lang=\"hi\">-143 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">42.5 h</span><span class=\"t\" lang=\"hi\">42.5 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.8 days</span><span class=\"t\" lang=\"hi\">1.8 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">421,700 km</span><span class=\"t\" lang=\"hi\">4,21,700 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Jupiter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Io formed from a disk of gas and dust around the young Jupiter, like a small solar system. Its orbit is locked in step with Europa and Ganymede, so Jupiter&#x27;s gravity keeps squeezing it, heating its inside. That is why Io has more volcanoes than any other world.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span></div><p><span class=\"t\" lang=\"en\">Rock and dust near Jupiter gather into Io.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span></div><p><span class=\"t\" lang=\"en\">Io, Europa and Ganymede fall into a 1:2:4 rhythm of orbits.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Ever since</span></div><p><span class=\"t\" lang=\"en\">Tidal squeezing melts rock; about 400 volcanoes erupt, and the surface is renewed all the time.</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Io is the most volcanic world we know, with hundreds of active volcanoes.</span></li><li><span class=\"t\" lang=\"en\">Jupiter&#x27;s gravity squeezes and stretches Io, and the heat from this powers its volcanoes.</span></li></ul><p><a class=\"btn primary\" href=\"body/io.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"europa":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/europa.webp\" alt=\"Europa\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Europa</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Jupiter</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3,122 km</span><span class=\"t\" lang=\"hi\">3,122 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.3 m/s² (0.13 g)</span><span class=\"t\" lang=\"hi\">1.3 m/s² (0.13 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-160 °C</span><span class=\"t\" lang=\"hi\">-160 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.6 days</span><span class=\"t\" lang=\"hi\">3.6 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.5 days</span><span class=\"t\" lang=\"hi\">3.5 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">670,900 km</span><span class=\"t\" lang=\"hi\">6,70,900 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Jupiter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Europa formed from rock and ice in the disk around Jupiter. Heat from tidal squeezing keeps a salty ocean liquid under its icy shell. Its surface has few craters, so the ice is young, perhaps 40 to 90 million years.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span></div><p><span class=\"t\" lang=\"en\">Rock and ice gather; a rocky core forms with water on top.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span></div><p><span class=\"t\" lang=\"en\">The outer water freezes into a shell, with an ocean left below.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Last ~100 million years</span></div><p><span class=\"t\" lang=\"en\">Cracks and ridges keep renewing the ice; plumes of water may escape.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Could the ocean hold life? NASA&#x27;s Europa Clipper, launched in 2024, arrives in 2030 to study it.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Under its icy shell, Europa probably holds about twice as much water as all of Earth&#x27;s oceans.</span></li><li><span class=\"t\" lang=\"en\">Europa is one of the best places to look for life beyond Earth. The Europa Clipper spacecraft is on its way there.</span></li></ul><p><a class=\"btn primary\" href=\"body/europa.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"ganymede":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/ganymede.webp\" alt=\"Ganymede\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Ganymede</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Jupiter</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,268 km</span><span class=\"t\" lang=\"hi\">5,268 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.4 m/s² (0.15 g)</span><span class=\"t\" lang=\"hi\">1.4 m/s² (0.15 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-163 °C</span><span class=\"t\" lang=\"hi\">-163 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">7.2 days</span><span class=\"t\" lang=\"hi\">7.2 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">7.2 days</span><span class=\"t\" lang=\"hi\">7.2 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,070,400 km</span><span class=\"t\" lang=\"hi\">10,70,400 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Jupiter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">The biggest moon in the solar system formed from rock and ice around Jupiter. It got warm enough inside to separate into layers, with an iron core that still makes its own magnetic field, the only moon known to have one.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span></div><p><span class=\"t\" lang=\"en\">Rock and ice gather into a huge moon.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span></div><p><span class=\"t\" lang=\"en\">It separates into an iron core, a rocky layer, ice and a deep ocean.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Billions of years</span></div><p><span class=\"t\" lang=\"en\">Old dark areas and younger grooved bright areas form on the surface.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">ESA&#x27;s JUICE spacecraft, launched in 2023, will orbit Ganymede from 2034 to study its hidden ocean.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Ganymede is the largest moon in the solar system. It is even bigger than Mercury.</span></li><li><span class=\"t\" lang=\"en\">Ganymede is the only moon known to have a magnetic field of its own.</span></li></ul><p><a class=\"btn primary\" href=\"body/ganymede.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"callisto":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/callisto.webp\" alt=\"Callisto\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Callisto</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Jupiter</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,821 km</span><span class=\"t\" lang=\"hi\">4,821 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.2 m/s² (0.13 g)</span><span class=\"t\" lang=\"hi\">1.2 m/s² (0.13 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-139 °C</span><span class=\"t\" lang=\"hi\">-139 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16.7 days</span><span class=\"t\" lang=\"hi\">16.7 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16.7 days</span><span class=\"t\" lang=\"hi\">16.7 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,882,700 km</span><span class=\"t\" lang=\"hi\">18,82,700 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Jupiter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Slowly, perhaps over a million years or more</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Callisto formed farthest out among Jupiter&#x27;s big moons and grew slowly, so it never got hot enough to fully separate rock from ice. It is not squeezed by tides, so its surface is the oldest and most cratered in the solar system.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First million years or more</span></div><p><span class=\"t\" lang=\"en\">Rock and ice slowly gather in the outer part of Jupiter&#x27;s disk.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4 billion years ago</span></div><p><span class=\"t\" lang=\"en\">Heavy bombardment covers it in craters, including the giant Valhalla basin.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Since then</span></div><p><span class=\"t\" lang=\"en\">Almost unchanged; Galileo found signs of a salty ocean deep inside.</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Callisto is one of the most heavily cratered places in the solar system, and its surface is very old.</span></li><li><span class=\"t\" lang=\"en\">Callisto is far enough from Jupiter to get less of its harsh radiation, so scientists have suggested it for a future base.</span></li></ul><p><a class=\"btn primary\" href=\"body/callisto.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"titan":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/titan.webp\" alt=\"Titan\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Titan</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Saturn</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,150 km</span><span class=\"t\" lang=\"hi\">5,150 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.4 m/s² (0.14 g)</span><span class=\"t\" lang=\"hi\">1.4 m/s² (0.14 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-179 °C</span><span class=\"t\" lang=\"hi\">-179 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">15.9 days</span><span class=\"t\" lang=\"hi\">15.9 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">15.9 days</span><span class=\"t\" lang=\"hi\">15.9 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,432 million km</span><span class=\"t\" lang=\"hi\">1,432 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,221,900 km</span><span class=\"t\" lang=\"hi\">12,21,900 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Saturn</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.45 bar</span><span class=\"t\" lang=\"hi\">1.45 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Saturn</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Titan formed from rock and ice in the disk around Saturn. It is the only moon with a thick atmosphere, mostly nitrogen, which may have come from ammonia ice broken apart long ago. Today it has rain, rivers and lakes of liquid methane.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span></div><p><span class=\"t\" lang=\"en\">Rock and ice gather into a moon bigger than Mercury.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on (unsure)</span></div><p><span class=\"t\" lang=\"en\">Its thick nitrogen air forms, perhaps from ammonia in its ice.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span></div><p><span class=\"t\" lang=\"en\">Methane rain fills lakes near the poles; an ocean of water lies deep below the ice.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Where Titan&#x27;s methane comes from, since sunlight keeps destroying it, is still a puzzle. NASA&#x27;s Dragonfly drone is due to arrive in 2034.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Titan is the only moon with a thick atmosphere. Its air pressure at the surface is higher than on Earth.</span></li><li><span class=\"t\" lang=\"en\">Titan has rivers and lakes, but they hold liquid methane and ethane, not water.</span></li></ul><p><a class=\"btn primary\" href=\"body/titan.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"enceladus":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/enceladus.webp\" alt=\"Enceladus\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Enceladus</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Saturn</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">504 km</span><span class=\"t\" lang=\"hi\">504 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.1 m/s² (0.01 g)</span><span class=\"t\" lang=\"hi\">0.1 m/s² (0.01 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-198 °C</span><span class=\"t\" lang=\"hi\">-198 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">32.9 h</span><span class=\"t\" lang=\"hi\">32.9 घंटे</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.4 days</span><span class=\"t\" lang=\"hi\">1.4 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,432 million km</span><span class=\"t\" lang=\"hi\">1,432 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">238,000 km</span><span class=\"t\" lang=\"hi\">2,38,000 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Saturn</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">With Saturn, about 4.6 billion years ago (some think later)</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Unknown</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Enceladus is a small moon of ice and rock. Tidal squeezing from Saturn heats it enough to keep a salty ocean under the south pole, which sprays water into space through cracks. Cassini flew through these jets and tasted salt and simple organic molecules.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago (or later)</span></div><p><span class=\"t\" lang=\"en\">Ice and rock gather into a small moon.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Over time</span></div><p><span class=\"t\" lang=\"en\">Tidal heating melts a global ocean under the ice shell.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span></div><p><span class=\"t\" lang=\"en\">More than 100 geysers spray from the &quot;tiger stripes&quot;; the spray feeds Saturn&#x27;s E ring.</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span>:</b> <span class=\"t\" lang=\"en\">Some models say Saturn&#x27;s mid-sized moons, Enceladus among them, are only about 100 million years old. Others say they are as old as Saturn. It is not settled.</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Enceladus shoots jets of ice and water vapour into space through cracks near its south pole.</span></li><li><span class=\"t\" lang=\"en\">The jets of Enceladus feed Saturn&#x27;s E ring.</span></li></ul><p><a class=\"btn primary\" href=\"body/enceladus.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"},"triton":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/triton.webp\" alt=\"Triton\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\">Triton</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\">Moon of Neptune</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2,707 km</span><span class=\"t\" lang=\"hi\">2,707 किमी</span></b><span><span class=\"t\" lang=\"en\">Diameter</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.8 m/s² (0.08 g)</span><span class=\"t\" lang=\"hi\">0.8 m/s² (0.08 g)</span></b><span><span class=\"t\" lang=\"en\">Gravity</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-235 °C</span><span class=\"t\" lang=\"hi\">-235 °C</span></b><span><span class=\"t\" lang=\"en\">Average temperature</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5.9 days</span><span class=\"t\" lang=\"hi\">5.9 दिन</span></b><span><span class=\"t\" lang=\"en\">Day</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5.9 days</span><span class=\"t\" lang=\"hi\">5.9 दिन</span></b><span><span class=\"t\" lang=\"en\">One orbit</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,515 million km</span><span class=\"t\" lang=\"hi\">4,515 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from the Sun</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">354,800 km</span><span class=\"t\" lang=\"hi\">3,54,800 किमी</span></b><span><span class=\"t\" lang=\"en\">Distance from Neptune</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">&lt; 0.001 bar</span><span class=\"t\" lang=\"hi\">&lt; 0.001 bar</span></b><span><span class=\"t\" lang=\"en\">Surface pressure</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">In the Kuiper Belt about 4.6 billion years ago; captured later</span></b><span><span class=\"t\" lang=\"en\">Formed</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Unknown</span></b><span><span class=\"t\" lang=\"en\">How long it took</span></span></div></div><p><span class=\"t\" lang=\"en\">Triton did not form around Neptune. It goes around Neptune backwards, which a moon born there would not do, so it was probably a dwarf planet like Pluto that Neptune captured. The capture heated and reshaped it.</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span></div><p><span class=\"t\" lang=\"en\">It forms in the Kuiper Belt, perhaps as one of a pair of bodies.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Later (unknown when)</span></div><p><span class=\"t\" lang=\"en\">Neptune captures it into a backwards orbit; tides heat it.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span></div><p><span class=\"t\" lang=\"en\">Voyager 2 (1989) saw nitrogen geysers and a young surface.</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">In billions of years</span></div><p><span class=\"t\" lang=\"en\">Its orbit slowly shrinks; Neptune&#x27;s gravity may tear it into a ring.</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span></p><h3><span class=\"t\" lang=\"en\">Did you know?</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\">Triton goes around Neptune backwards, so it was probably a dwarf planet that Neptune captured.</span></li><li><span class=\"t\" lang=\"en\">At about −235 °C, Triton is one of the coldest places anyone has measured in the solar system.</span></li></ul><p><a class=\"btn primary\" href=\"body/triton.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span> →</a></p>"}};